<?php
require_once __DIR__ . '/../includes/bootstrap.php';
header('Content-Type: application/json; charset=utf-8');

function api_out(mixed $data, int $status = 200): never { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_UNICODE); exit; }
function api_body(): array { $raw=file_get_contents('php://input'); $json=json_decode($raw,true); return is_array($json)?$json:$_POST; }
function api_error(string $message,int $status=400): never { api_out(['error'=>$message],$status); }

$resource = $resource ?? ($_GET['resource'] ?? ''); $method=$_SERVER['REQUEST_METHOD']; $id=(int)($_GET['id']??0); $body=api_body();
try {
  if($resource==='seed' && $method==='GET') { pdo(); api_out(['message'=>'Database siap. Data demo dibuat otomatis saat database masih kosong.']); }
  if($resource==='dashboard' && $method==='GET') {
    api_out(['stats'=>['totalBooks'=>count_of('books'),'totalMembers'=>count_of('users',"role='member'"),'totalPublishers'=>count_of('publishers'),'activeBorrowings'=>count_of('borrowings',"status='active'"),'overdueBorrowings'=>count_of('borrowings',"status='overdue'"),'todayAttendance'=>count_of('attendances','date(check_in)=date("now")'),'activeVisitors'=>count_of('attendances','check_out IS NULL'),'pendingExtensions'=>count_of('extensions',"status='pending'"),'unpaidFinesTotal'=>(int)one("SELECT COALESCE(SUM(amount),0) AS amount FROM fines WHERE status='unpaid'")['amount']]]);
  }
  if($resource==='books') {
    if($method==='GET') { $q=trim($_GET['search']??''); $sql='SELECT b.*,p.name publisher_name FROM books b LEFT JOIN publishers p ON p.id=b.publisher_id'; $params=[]; if($id){$sql.=' WHERE b.id=?';$params=[$id];} elseif($q){$sql.=' WHERE b.title LIKE ? OR b.author LIKE ? OR b.book_id LIKE ?';$params=array_fill(0,3,'%'.$q.'%');} api_out($id?(one($sql,$params)??api_error('Not found',404)):rows($sql.' ORDER BY b.title',$params)); }
    if($method==='POST'){execute('INSERT INTO books (book_id,title,author,year,pages,genre,stock,available,publisher_id) VALUES (?,?,?,?,?,?,?,?,?)',[$body['bookId']??$body['book_id'],$body['title']??'',$body['author']??'',(int)($body['year']??0),(int)($body['pages']??0),$body['genre']??'',(int)($body['stock']??0),(int)($body['stock']??0),$body['publisherId']??$body['publisher_id']??null]);api_out(one('SELECT * FROM books WHERE id=last_insert_rowid()'),201);}
    if(in_array($method,['PUT','PATCH'],true)&&$id){execute('UPDATE books SET title=?,author=?,year=?,pages=?,genre=?,stock=?,publisher_id=? WHERE id=?',[$body['title']??'',$body['author']??'',(int)($body['year']??0),(int)($body['pages']??0),$body['genre']??'',(int)($body['stock']??0),$body['publisherId']??null,$id]);api_out(one('SELECT * FROM books WHERE id=?',[$id]));}
    if($method==='DELETE'&&$id){execute('DELETE FROM books WHERE id=?',[$id]);api_out(['message'=>'Deleted']);}
  }
  if($resource==='members') {
    if($method==='GET'){ $q=trim($_GET['search']??'');$sql="SELECT id,member_id,nis,name,kelas,email,phone,gender,address,role,status,created_at FROM users WHERE role='member'";$params=[];if($id){$sql.=' AND id=?';$params=[$id];}elseif($q){$sql.=' AND (name LIKE ? OR member_id LIKE ? OR nis LIKE ? OR email LIKE ?)';$params=array_fill(0,4,'%'.$q.'%');}api_out($id?(one($sql,$params)??api_error('Not found',404)):rows($sql.' ORDER BY member_id',$params)); }
    api_error('Operasi CRUD user dinonaktifkan.', 405);
  }
  if($resource==='publishers') {
    if($method==='GET') api_out($id?(one('SELECT p.*,COUNT(b.id) books_count FROM publishers p LEFT JOIN books b ON b.publisher_id=p.id WHERE p.id=? GROUP BY p.id',[$id])??api_error('Not found',404)):rows('SELECT p.*,COUNT(b.id) books_count FROM publishers p LEFT JOIN books b ON b.publisher_id=p.id GROUP BY p.id ORDER BY p.name'));
    if($method==='POST'){execute('INSERT INTO publishers (name,location) VALUES (?,?)',[$body['name']??'',$body['location']??null]);api_out(['message'=>'Created'],201);}
    if(in_array($method,['PUT','PATCH'],true)&&$id){execute('UPDATE publishers SET name=?,location=? WHERE id=?',[$body['name']??'',$body['location']??null,$id]);api_out(['message'=>'Updated']);}
    if($method==='DELETE'&&$id){execute('DELETE FROM publishers WHERE id=?',[$id]);api_out(['message'=>'Deleted']);}
  }
  if($resource==='borrowings') {
    if($method==='GET') api_out(rows('SELECT br.*,u.member_id,u.name,b.book_id,b.title FROM borrowings br JOIN users u ON u.id=br.user_id JOIN books b ON b.id=br.book_id ORDER BY br.borrowed_at DESC'));
    if($method==='POST'){ $user=one('SELECT * FROM users WHERE member_id=?',[$body['memberId']??'']);$book=one('SELECT * FROM books WHERE book_id=?',[$body['bookId']??'']);if(!$user||!$book)api_error('Anggota atau buku tidak ditemukan',404);if(!$book['available'])api_error('Buku tidak tersedia');execute('INSERT INTO borrowings (user_id,book_id,due_date) VALUES (?,?,?)',[$user['id'],$book['id'],date('Y-m-d H:i:s',strtotime('+7 days'))]);execute('UPDATE books SET available=available-1 WHERE id=?',[$book['id']]);api_out(['message'=>'Borrowed'],201);}
  }
  if($resource==='returns'&&$method==='POST'){ $user=one('SELECT * FROM users WHERE member_id=?',[$body['memberId']??'']);$book=one('SELECT * FROM books WHERE book_id=?',[$body['bookId']??'']);$borrowing=$user&&$book?one('SELECT * FROM borrowings WHERE user_id=? AND book_id=? AND status IN ("active","overdue")',[$user['id'],$book['id']]):null;if(!$borrowing)api_error('Peminjaman tidak ditemukan',404);$late=max(0,(int)floor((time()-strtotime($borrowing['due_date']))/86400));execute('UPDATE borrowings SET returned_at=CURRENT_TIMESTAMP,status="returned" WHERE id=?',[$borrowing['id']]);execute('UPDATE books SET available=available+1 WHERE id=?',[$book['id']]);if($late)execute('INSERT INTO fines (user_id,borrowing_id,days_late,amount) VALUES (?,?,?,?)',[$user['id'],$borrowing['id'],$late,$late*1000]);api_out(['message'=>'Pengembalian berhasil','daysLate'=>$late,'fineAmount'=>$late*1000]); }
  if($resource==='attendance') { if($method==='GET')api_out(rows('SELECT a.*,u.member_id,u.name FROM attendances a JOIN users u ON u.id=a.user_id ORDER BY a.check_in DESC LIMIT 100')); if($method==='POST'){ $user=one('SELECT * FROM users WHERE member_id=?',[$body['memberId']??'']);if(!$user)api_error('Anggota tidak ditemukan',404);$active=one('SELECT * FROM attendances WHERE user_id=? AND check_out IS NULL',[$user['id']]);if($active){execute('UPDATE attendances SET check_out=CURRENT_TIMESTAMP,duration=CAST((julianday(CURRENT_TIMESTAMP)-julianday(check_in))*1440 AS INTEGER) WHERE id=?',[$active['id']]);api_out(['type'=>'checkout']);}execute('INSERT INTO attendances (user_id) VALUES (?)',[$user['id']]);api_out(['type'=>'checkin'],201);}}
  if($resource==='fines'){if($method==='GET')api_out(rows('SELECT f.*,u.member_id,u.name,b.title FROM fines f JOIN users u ON u.id=f.user_id LEFT JOIN borrowings br ON br.id=f.borrowing_id LEFT JOIN books b ON b.id=br.book_id ORDER BY f.created_at DESC'));if(in_array($method,['PUT','PATCH'],true)){execute('UPDATE fines SET status=?,notes=? WHERE id=?',[$body['status']??'unpaid',$body['notes']??null,(int)$body['id']]);api_out(['message'=>'Updated']);}}
  if($resource==='budget'){if($method==='GET')api_out(rows('SELECT * FROM budgets ORDER BY date DESC'));if($method==='POST'){execute('INSERT INTO budgets (category,description,amount,type,date) VALUES (?,?,?,?,?)',[$body['category']??'other',$body['description']??'',(int)($body['amount']??0),$body['type']??'expense',$body['date']??date('Y-m-d')]);api_out(['message'=>'Created'],201);}}
  if($resource==='extensions'){if($method==='GET')api_out(rows('SELECT e.*,u.member_id,u.name,b.title FROM extensions e JOIN users u ON u.id=e.user_id JOIN borrowings br ON br.id=e.borrowing_id JOIN books b ON b.id=br.book_id ORDER BY e.requested_at DESC'));if($method==='POST'){execute('INSERT INTO extensions (user_id,borrowing_id) VALUES (?,?)',[(int)$body['userId'],(int)$body['borrowingId']]);api_out(['message'=>'Created'],201);}}
  if($resource==='complaints'){if($method==='GET')api_out(rows('SELECT c.*,u.member_id,u.name,b.title FROM complaints c JOIN users u ON u.id=c.user_id JOIN books b ON b.id=c.book_id ORDER BY c.created_at DESC'));if($method==='POST'){ $book=one('SELECT * FROM books WHERE book_id=?',[$body['bookId']??'']);if(!$book)api_error('Buku tidak ditemukan',404);execute('INSERT INTO complaints (user_id,book_id,type,description) VALUES (?,?,?,?)',[(int)$body['userId'],$book['id'],$body['type']??'damaged',$body['description']??null]);api_out(['message'=>'Created'],201);}}
  api_error('Endpoint atau metode tidak tersedia.',404);
} catch (Throwable $error) { api_error('Permintaan gagal diproses: ' . $error->getMessage(),500); }
